def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = history[-1]

    my_d = opp_d = cc_total = dd_total = cd_total = dc_total = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
        if a == 'C' and b == 'C':
            cc_total += 1
        elif a == 'D' and b == 'D':
            dd_total += 1
        elif a == 'C' and b == 'D':
            cd_total += 1
        else:
            dc_total += 1

    od_streak = 0
    for x in reversed(opp):
        if x == 'D':
            od_streak += 1
        else:
            break

    cd_streak = 0
    for a, b in reversed(history):
        if a == 'C' and b == 'D':
            cd_streak += 1
        else:
            break

    dc_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'C':
            dc_streak += 1
        else:
            break

    recent5_oppD = sum(1 for x in opp[-5:] if x == 'D')
    recent5_myD = sum(1 for x in me[-5:] if x == 'D')
    recent10_oppD = sum(1 for x in opp[-10:] if x == 'D')

    punish = tolerate = recent_punish = recent_tolerate = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            if opp[i] == 'D':
                punish += 1
                if i >= n - 10:
                    recent_punish += 1
            else:
                tolerate += 1
                if i >= n - 10:
                    recent_tolerate += 1

    if n <= 2:
        return 'C'

    hostile = False
    if n >= 15 and cd_total >= 4 and cc_total <= cd_total and opp_d * 2 >= n:
        hostile = True
    if opp_d * 2 >= n + 8:
        hostile = True
    if od_streak >= 8 and opp_d >= 5:
        hostile = True
    if recent10_oppD >= 9:
        hostile = True
    if opp_d > 50:
        hostile = True

    if hostile:
        return 'D'

    if last_opp == 'D':
        if od_streak >= 5:
            return 'D'

        if cd_streak >= 2:
            if history[-2] == ('D', 'C') or history[-2] == ('D', 'D'):
                return 'C'
            return 'D'

        if history[-2] == ('D', 'C') or history[-2] == ('D', 'D'):
            return 'C'

        if history[-2] == ('C', 'C') and opp_d <= max(2, n // 5):
            return 'C'

        if recent5_oppD >= 3 and recent5_myD <= 1:
            return 'D'

        if od_streak >= 2 and opp_d * 3 >= n:
            return 'D'

        return 'C'

    if last_opp == 'C':
        if opp_d == 0:
            if last_me == 'D' or my_d > 0:
                return 'D'
            if n >= 98:
                return 'D'
            if n > 5 and rng.random() < 0.02:
                return 'D'
            return 'C'

        if last_me == 'D':
            if dc_streak >= 2 and recent_punish == 0:
                return 'D'
            if punish == 0 and (opp_d <= max(2, n // 5) or n >= 98):
                return 'D'
            if recent_tolerate >= 2 and recent_punish == 0:
                return 'D'
            return 'C'

        if recent5_oppD >= 2 and recent5_myD <= 2 and opp_d <= max(5, n // 3):
            if recent_punish <= 1 and punish <= 3 and cd_streak <= 1:
                return 'D'

        if opp_d <= max(2, n // 8) and punish == 0 and my_d <= max(1, n // 8):
            if n >= 80:
                if rng.random() < 0.04:
                    return 'D'
            elif n > 10:
                if rng.random() < 0.01:
                    return 'D'

        if n >= 98 and (opp_d == 0 or recent_tolerate >= 2 or tolerate >= 2):
            return 'D'

        return 'C'

    return 'C'
